export interface ConnectorConfig {
  /** Slack Bot Token with chat:write scope */
  slackBotToken: string
  /** Slack channel ID (e.g., C01JASD6802) or name (e.g., #general) */
  slackChannel: string
  /** Optional custom fetch for testing or proxying */
  fetch?: typeof fetch
}

export interface CalendlyWebhookPayload {
  resource: {
    type: string
    uri: string
  }
  invitee: {
    name: string
    email: string
    uri: string
  }
  answers: Record<string, string>
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  slackMessage: SlackPostMessageResponse
}

const SLACK_API_URL = 'https://slack.com/api/chat.postMessage'

function validatePayload(payload: unknown): asserts payload is CalendlyWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.invitee || typeof p.invitee !== 'object') {
    throw new Error('Missing required field: invitee')
  }
  const invitee = p.invitee as Record<string, unknown>
  if (typeof invitee.name !== 'string' || !invitee.name.trim()) {
    throw new Error('Missing required field: invitee.name')
  }
  if (typeof invitee.email !== 'string' || !invitee.email.trim()) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!p.answers || typeof p.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
}

function formatSlackMessage(payload: CalendlyWebhookPayload): string {
  const { invitee, answers } = payload
  const answersLines = Object.entries(answers)
    .map(([question, answer]) => `${question} -> ${answer}`)
    .join(', ')
  return [
    'New meeting booked!',
    `Invitee: ${invitee.name}`,
    `Email: ${invitee.email}`,
    answersLines ? `Answers: ${answersLines}` : 'Answers: (none)'
  ].join('\n')
}

export async function handle(
  payload: CalendlyWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const { slackBotToken, slackChannel, fetch: customFetch } = config
  const fetchFn = customFetch ?? fetch

  const text = formatSlackMessage(payload)
  const body = JSON.stringify({ channel: slackChannel, text })

  const response = await fetchFn(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${SLACK_API_URL}`)
  }

  const data = await response.json() as SlackPostMessageResponse
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return { slackMessage: data }
}

