      expect(req.url).toBe('https://slack.com/api/chat.postMessage')
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-test-token')
      expect(req.json).toEqual({
        channel: 'C01JASD6802',
        text: 'New meeting booked!\nInvitee: Jane Doe\nEmail: jane.doe@example.com\nAnswers: What is your company? -> Acme Corp, How did you hear about us? -> Google'
      })
      return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '1740000000.000200' })
    })

    const payload: CalendlyWebhookPayload = {
      resource: { type: 'scheduled_event', uri: 'https://api.calendly.com/scheduled_events/AAAAAAAAAAAAAAAA' },
      invitee: { name: 'Jane Doe', email: 'jane.doe@example.com', uri: 'https://api.calendly.com/scheduled_events/AAAAAAAAAAAAAAAA/invitees/BBBBBBBBBBBBBBBB' },
      answers: { 'What is your company?': 'Acme Corp', 'How did you hear about us?': 'Google' }
    }

    const result = await handle(payload, {
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C01JASD6802',
      fetch
    })

    expect(result.slackMessage).toEqual({ ok: true, channel: 'C01JASD6802', ts: '1740000000.000200' })
    expect(calls).toHaveLength(1)
  })

  it('includes Authorization header with Bearer token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-secret-123')
      return jsonResponse({ ok: true, channel: 'C123', ts: '1.2' })
    })

    await handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'A', email: 'a@b.com', uri: 'u' },
      answers: {}
    }, { slackBotToken: 'xoxb-secret-123', slackChannel: 'C123', fetch })

    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-secret-123')
  })

  it('maps invitee.name, invitee.email, and answers into Slack text', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ ok: true, channel: 'C1', ts: '1' }))

    await handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'John Smith', email: 'john@smith.io', uri: 'u' },
      answers: { 'Question?': 'Answer' }
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })

    const sent = calls[0].json as { text: string }
    expect(sent.text).toContain('Invitee: John Smith')
    expect(sent.text).toContain('Email: john@smith.io')
    expect(sent.text).toContain('Question? -> Answer')
  })

  it('throws on missing invitee.name', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: '', email: 'a@b.com', uri: 'u' },
      answers: {}
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })).rejects.toThrow('Missing required field: invitee.name')
  })

  it('throws on missing invitee.email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'A', email: '', uri: 'u' },
      answers: {}
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })).rejects.toThrow('Missing required field: invitee.email')
  })

  it('throws on missing answers field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'A', email: 'a@b.com', uri: 'u' },
      answers: null as unknown as Record<string, string>
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })).rejects.toThrow('Missing required field: answers')
  })

  it('throws on non-2xx response from Slack', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    await expect(handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'A', email: 'a@b.com', uri: 'u' },
      answers: {}
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })).rejects.toThrow('Slack API error: 401 Unauthorized at https://slack.com/api/chat.postMessage')
    expect(calls).toHaveLength(1)
  })

