    await expect(handle({
      resource: { type: 'scheduled_event', uri: 'u' },
      invitee: { name: 'A', email: 'a@b.com', uri: 'u' },
      answers: {}
    }, { slackBotToken: 't', slackChannel: 'C1', fetch })).rejects.toThrow('Slack API returned ok=false')
  })
})

